def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if grid[r] and len(set(grid[r])) == 1 and grid[r][0] != 0]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0]

    def ranges(n, separators):
        bounds = [-1] + separators + [n]
        return [(bounds[i] + 1, bounds[i + 1]) for i in range(len(bounds) - 1)
                if bounds[i] + 1 < bounds[i + 1]]

    rr = ranges(h, sep_rows)
    cc = ranges(w, sep_cols)
    out = [row[:] for row in grid]
    cells = {}

    for i, (r0, r1) in enumerate(rr):
        for j, (c0, c1) in enumerate(cc):
            colors = {}
            for r in range(r0, r1):
                for c in range(c0, c1):
                    v = grid[r][c]
                    if v:
                        colors.setdefault(v, set()).add((r - r0, c - c0))
            for color, pts in colors.items():
                cells[(i, j, color)] = (r0, r1, c0, c1, pts)

    for color in {key[2] for key in cells}:
        for i in range(len(rr) - 1):
            for j in range(len(cc) - 1):
                coords = [(i, j), (i, j + 1), (i + 1, j), (i + 1, j + 1)]
                present = [p for p in coords if (p[0], p[1], color) in cells]
                if len(present) != 3:
                    continue
                missing = next(p for p in coords if p not in present)
                mi, mj = missing

                # Prefer the occupied cell in the same row, reflecting across
                # the vertical axis; otherwise use the same column.
                same_row = [p for p in present if p[0] == mi]
                same_col = [p for p in present if p[1] == mj]
                if same_row:
                    si, sj = same_row[0]
                    sr0, sr1, sc0, sc1, pts = cells[(si, sj, color)]
                    width = sc1 - sc0
                    reflected = {(r, width - 1 - c) for r, c in pts}
                elif same_col:
                    si, sj = same_col[0]
                    sr0, sr1, sc0, sc1, pts = cells[(si, sj, color)]
                    height = sr1 - sr0
                    reflected = {(height - 1 - r, c) for r, c in pts}
                else:
                    continue

                r0, r1 = rr[mi]
                c0, c1 = cc[mj]
                for r, c in reflected:
                    if r < r1 - r0 and c < c1 - c0:
                        out[r0 + r][c0 + c] = color

    return out
